Installer:RegisterAddon({
    key = "EXBoss",
    title = "|cffff4400Ex|r|cff00ccffBoss|r",
    description = "EXBoss is a World of Warcraft boss encounter addon with timeline bars, central alerts, and voice warnings.",
    folder = "EXBoss",
    version = "1",
    needsReload = false,
    profile = profileString,
    apply = function(def, payload)
        local ExBoss = _G.ExBoss
        local ImportExport = ExBoss and ExBoss.Voice and ExBoss.Voice.ImportExport

        if not (ImportExport and ImportExport.ImportString) then
            return false, "EXBoss' import API is not available"
        end

        local ok, message = ImportExport:ImportString(payload)

        if not ok then
            return false, message
        end

        return true
    end,
})
